"""Modern migration of the Meridian CRM order-total recompute job."""

from decimal import Decimal, ROUND_HALF_UP, localcontext


_CENTS = Decimal("0.01")
_HUNDRED = Decimal("100")


def _decimal(value) -> Decimal:
    """Convert legacy numeric input to Decimal, treating blank/missing as zero."""
    if value is None:
        return Decimal(0)
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return Decimal(0)
    if isinstance(value, bool):
        return Decimal(int(value))
    # str(float_value) intentionally avoids importing binary float artifacts.
    return Decimal(str(value))


def _precision_needed(values: list[Decimal]) -> int:
    """Choose sufficient decimal working precision for arithmetic and cent rounding."""
    required = 50
    for value in values:
        if value:
            required += max(0, value.adjusted() + 1) + len(value.as_tuple().digits)
    return required


def _cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    """Recompute one eligible order's line extensions and discounted total."""
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    live_values: list[tuple[int, Decimal, Decimal]] = []
    precision_values = [_decimal(order.get("DISC_PCT")), _decimal(order.get("TOT_AMT"))]

    for index, line in enumerate(lines):
        if line.get("DEL_FLG") != "Y":
            qty = _decimal(line.get("QTY"))
            unit_price = _decimal(line.get("UNIT_PRC"))
            live_values.append((index, qty, unit_price))
            precision_values.extend((qty, unit_price))

    with localcontext() as context:
        context.prec = _precision_needed(precision_values)

        total = Decimal(0)
        for index, qty, unit_price in live_values:
            extension = _cents(qty * unit_price)
            new_lines[index]["EXT_AMT"] = float(extension)
            total += extension

        discount_pct = _decimal(order.get("DISC_PCT"))
        discounted = _cents(total * (_HUNDRED - discount_pct) / _HUNDRED)

        incoming_total = _decimal(order.get("TOT_AMT"))
        new_order["TOT_AMT"] = float(discounted)

        audits = []
        if incoming_total != discounted:
            audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
